
const dossier=document.querySelector('.dossier'),page=dossier.querySelector('.dossier-page'),sigil=document.querySelector('.sigil-wipe');const asset=id=>`../assets/guild/${id}.svg`;
function openHost(id,el){const h=PROTO.byId(id);PROTO.state.selected=id;const old=el,newImg=page.querySelector('[data-detail-img]');old.style.viewTransitionName='unit-card';PROTO.vt(()=>{old.style.viewTransitionName='';newImg.style.viewTransitionName='unit-card';PROTO.fillDetail(page,h,asset(id));dossier.classList.add('open');dossier.setAttribute('aria-hidden','false')},'dossier').finally(()=>{old.style.viewTransitionName='';newImg.style.viewTransitionName=''})}
function closeDetail(silent=false){if(!dossier.classList.contains('open'))return;PROTO.vt(()=>{dossier.classList.remove('open');dossier.setAttribute('aria-hidden','true')},'dossier-close');PROTO.state.selected=null}
document.querySelectorAll('.unit-card').forEach(el=>el.addEventListener('click',()=>openHost(el.dataset.host,el)));dossier.querySelector('.close-detail').onclick=()=>closeDetail();dossier.querySelector('.dossier-backdrop').onclick=()=>closeDetail();PROTO.onEscape(closeDetail);PROTO.bindNav({closeDetail,before(){sigil.classList.remove('go');void sigil.offsetWidth;sigil.classList.add('go')}});PROTO.bindSettings();
